<script setup>import {ref} from 'vue';import DriverShell from '../../components/DriverShell.vue';import AppIcon from '../../components/AppIcon.vue';import StatusPill from '../../components/StatusPill.vue';import {orders,timeline} from '../../api/mock';const tab=ref('进度');</script>
<template><DriverShell><div class="task-top"><RouterLink to="/driver/home">‹</RouterLink><div><small>运输任务</small><h1>{{orders[0].no}}</h1></div><button>•••</button></div><section class="task-route-card"><div class="task-route-head"><StatusPill status="运输中"/><span>预计提前 10 分钟到达</span></div><div class="task-city"><div><small>提货地</small><b>上海·松江</b><span>09:16 已提货</span></div><div class="route-arrow"><span>68 km</span><i></i><AppIcon name="truck"/></div><div class="right"><small>送货地</small><b>杭州·滨江</b><span>预计 14:20</span></div></div><button class="nav-button"><AppIcon name="map"/>继续导航<span>剩余约 58 分钟</span></button></section><div class="task-tabs"><button v-for="t in ['进度','货物','联系人']" :class="{active:tab===t}" @click="tab=t">{{t}}</button></div><section v-if="tab==='进度'" class="timeline-card"><div class="timeline-title"><h2>运输轨迹</h2><span><i></i>定位正常</span></div><article v-for="(e,i) in timeline" :key="e.time" class="timeline-item"><time>{{e.time}}</time><div class="timeline-mark" :class="{current:i===0}"><i></i></div><div><b>{{e.title}}</b><p>{{e.detail}}</p></div></article></section><section v-else-if="tab==='货物'" class="mobile-info-card"><h2>货物信息</h2><dl><div><dt>货物名称</dt><dd>工业控制柜 18 台</dd></div><div><dt>重量 / 体积</dt><dd>8.6 t / 42 m³</dd></div><div><dt>封签号</dt><dd>SH26073018</dd></div><div><dt>运输要求</dt><dd>防雨、防倾倒，轻装轻卸</dd></div></dl></section><section v-else class="mobile-info-card"><h2>任务联系人</h2><dl><div><dt>发货联系人</dt><dd>王经理 · 138****2018</dd></div><div><dt>收货联系人</dt><dd>赵主管 · 139****6281</dd></div><div><dt>调度专员</dt><dd>林泽宇 · 137****9036</dd></div></dl></section><div class="driver-bottom-actions"><button class="secondary-btn"><AppIcon name="bell"/>异常上报</button><button class="primary-btn"><AppIcon name="check"/>到达卸货点</button></div></DriverShell></template>
